EXTRA_POEMS = [{'id': '95c6417fd951bf350ab4', 'title': '山居秋暝', 'author': '王維', 'category': '唐诗', 'paragraphs': ['空山新雨後，天氣晚來秋。', '明月松間照，清泉石上流。', '竹喧歸浣女，蓮動下漁舟。', '隨意春芳歇，王孫自可留。'], 'featured': True}, {'id': '55d15a8a407dbfbb14e2', 'title': '靜夜思', 'author': '李白', 'category': '唐诗', 'paragraphs': ['床前明月光，疑是地上霜，', '舉頭望明月，低頭思故鄉。'], 'featured': True}, {'id': '444bcb23fd1d873d3cff', 'title': '春曉', 'author': '孟浩然', 'category': '唐诗', 'paragraphs': ['春眠不覺曉，處處聞啼鳥。', '夜來風雨聲，花落知多少。'], 'featured': True}, {'id': '8b21e87093ed074ae68f', 'title': '登鸛雀樓', 'author': '王之渙', 'category': '唐诗', 'paragraphs': ['白日依山盡，黃河入海流。', '欲窮千里目，更上一層樓。'], 'featured': True}, {'id': 'd65be89288f7b20e5776', 'title': '相思', 'author': '王維', 'category': '唐诗', 'paragraphs': ['紅豆生南國，春來發幾枝。', '願君多采擷，此物最相思。'], 'featured': True}, {'id': 'ed73a2d2cdcc5635c103', 'title': '鹿柴', 'author': '王維', 'category': '唐诗', 'paragraphs': ['空山不見人，但聞人語響。', '返景入深林，復照青苔上。'], 'featured': True}, {'id': '434f0fa141b63b0f4eca', 'title': '江雪', 'author': '柳宗元', 'category': '唐诗', 'paragraphs': ['千山鳥飛絕，萬徑人蹤滅。', '孤舟蓑笠翁，獨釣寒江雪。'], 'featured': True}, {'id': '2b4613e6ada23b42d641', 'title': '九月九日憶山東兄弟', 'author': '王維', 'category': '唐诗', 'paragraphs': ['獨在異鄉爲異客，每逢佳節倍思親。', '遙知兄弟登高處，遍插茱萸少一人。'], 'featured': True}, {'id': '7d410058ac73d7376959', 'title': '早發白帝城', 'author': '李白', 'category': '唐诗', 'paragraphs': ['朝辭白帝彩雲間，千里江陵一日還。', '兩岸猿聲啼不住，輕舟已過萬重山。'], 'featured': True}, {'id': '231106daa6ad1e436ee7', 'title': '遊子吟', 'author': '孟郊', 'category': '唐诗', 'paragraphs': ['慈母手中線，遊子身上衣。', '臨行密密縫，意恐遲遲歸。', '誰言寸草心，報得三春暉。'], 'featured': True}]
READINGS = {'95c6417fd951bf350ab4': {'translation': '雨后秋山清新宁静，月光、松林、清泉与归舟构成可居可游的山间生活。结尾表达对眼前山居的喜爱。', 'imagery': '明月与清泉一静一动；先听见竹林喧声，再知道是浣女归来；先看到莲叶摇动，再见渔舟经过。', 'analysis': '写景中有人物活动，画面清幽却不空寂。留意“照、流、喧、动”怎样调动视觉与听觉。', 'question': '“竹喧”和“莲动”为什么先写声音、动静，再点明人物？', 'credit': '本应用编辑撰写的学习参考，非权威定论；原文按上游版本保留。'}, '55d15a8a407dbfbb14e2': {'translation': '月光像霜一样洒在床前，诗人由望月转向思念故乡。', 'imagery': '月光、霜、故乡把眼前所见和内心情绪连接起来。', 'analysis': '“举头”和“低头”两个动作使视线由外向内，语言浅近，情感集中。', 'question': '如果去掉“疑”字，开头的感受会怎样变化？', 'credit': '本应用编辑撰写的学习参考，非权威定论；原文按上游版本保留。'}, '444bcb23fd1d873d3cff': {'translation': '春日醒来听到鸟鸣，想到夜里的风雨，转而牵挂庭院的落花。', 'imagery': '鸟声带来春意，风雨与落花又让人感到春光容易流逝。', 'analysis': '诗从听觉展开，以疑问收束，惜春之情含在问句中。', 'question': '诗人哪些景物是当下听见的，哪些是回想或推想的？', 'credit': '本应用编辑撰写的学习参考，非权威定论；原文按上游版本保留。'}, '8b21e87093ed074ae68f': {'translation': '夕阳依山而落，黄河奔流入海。想看到更远的景色，还要再登一层楼。', 'imagery': '山、夕阳与大河打开广阔的空间。', 'analysis': '前两句写所见，后两句写登高愿望；可以由登楼联想到扩大视野，但应先理解具体景象。', 'question': '“欲穷”和“更上”之间是什么关系？', 'credit': '本应用编辑撰写的学习参考，非权威定论；原文按上游版本保留。'}, 'd65be89288f7b20e5776': {'translation': '诗人借红豆寄托对远方之人的惦念，愿对方多多采撷。', 'imagery': '红豆从具体植物成为情意的载体。', 'analysis': '由问生长情况转为劝采红豆，表达含蓄而亲切。', 'question': '“多采撷”怎样让思念变得可以触摸？', 'credit': '本应用编辑撰写的学习参考，非权威定论；原文按上游版本保留。'}, 'ed73a2d2cdcc5635c103': {'translation': '空山不见人影，只听到说话声；夕阳返照进入深林，映亮青苔。', 'imagery': '人语、返照与青苔都是静谧山林中的细微变化。', 'analysis': '用声音衬托寂静，用局部亮光表现深林幽暗，注意感官之间的转换。', 'question': '有人说话，为什么仍然会感到山林幽静？', 'credit': '本应用编辑撰写的学习参考，非权威定论；原文按上游版本保留。'}, '434f0fa141b63b0f4eca': {'translation': '鸟迹、人迹都消失在寒冷的天地里，只有一位披蓑戴笠的老人独自垂钓。', 'imagery': '千山、万径、孤舟与独钓形成数量和空间的强烈对照。', 'analysis': '先铺开大范围的空寂，再聚焦一个人。可以讨论孤独或坚守，但不必把人物心理解释成唯一答案。', 'question': '前两句的“千、万”和后两句的“孤、独”怎样互相映衬？', 'credit': '本应用编辑撰写的学习参考，非权威定论；原文按上游版本保留。'}, '2b4613e6ada23b42d641': {'translation': '独在异乡，节日里格外想念亲人；诗人想象兄弟们登高时会觉得少了一人。', 'imagery': '佳节、登高、茱萸把亲情放入具体的生活场景。', 'analysis': '后半从想念别人转为想象别人想念自己，换一个视角让情感更深。', 'question': '为什么不只写“我想家”，还要写兄弟们“少一人”？', 'credit': '本应用编辑撰写的学习参考，非权威定论；原文按上游版本保留。'}, '7d410058ac73d7376959': {'translation': '清晨告别白帝城，舟行迅速，仿佛猿声还没听完，轻舟就已穿过重重山岭。', 'imagery': '彩云、猿声、轻舟与万重山交织成迅疾而明亮的旅途。', 'analysis': '“一日还”“啼不住”“已过”一起压缩时间，读时体会轻快的节奏。', 'question': '诗中哪些词让你感觉舟行很快？', 'credit': '本应用编辑撰写的学习参考，非权威定论；原文按上游版本保留。'}, '231106daa6ad1e436ee7': {'translation': '母亲临行前为孩子缝衣，担心归期迟迟；孩子感到自己的报答难及母爱。', 'imagery': '手中线、身上衣、寸草与春晖都来自日常生活。', 'analysis': '先用细小动作写关怀，再以寸草和春晖作比，感情由具体场景自然升起。', 'question': '“密密缝”与“迟迟归”之间藏着怎样的牵挂？', 'credit': '本应用编辑撰写的学习参考，非权威定论；原文按上游版本保留。'}}
